-- Namuna yechimlar: har biri «qanday ishlaydi» bo'limlari va bosib ko'riladigan demo suhbati bilan.
-- Mavjud yozuv (admin o'zgartirgan bo'lsa ham) almashtirilmaydi. sado.alifbit.org loyihasi ro'yxatdan chiqariladi.
INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('tungi-navbatchi','tungi-navbatchi','{"id":"tungi-navbatchi","slug":"tungi-navbatchi","name":"Tungi navbatchi","category":"AI","status":"Namuna","summary":"Mijozlar savoliga kechayu kunduz javob beradigan va arizani tayyor holda menejerga uzatadigan AI yordamchi.","description":"Tungi navbatchi sizning narxlaringiz, xizmatlaringiz va qoidalaringiz asosida javob beradi. Telegram’da yoki saytingizdagi chat oynasida ishlaydi. Mijoz nima kerakligini, byudjeti va muddatini aytsa, yordamchi arizani tartibli kartochka holida menejerga uzatadi. Javobini bilmagan savolni o‘ylab topmaydi — xodimga yo‘naltiradi.","purpose":"Mijoz javob kutib boshqa joyga ketib qolmasligi, menejer esa kun bo‘yi bir xil savollarga javob bermasligi.","features":["Narx, xizmat, manzil va ish vaqti bo‘yicha javob — o‘z bilimlar bazangizdan","O‘zbek (lotin va kirill) va rus tillarida","Mijozni saralash: nima kerak, byudjet, muddat","Arizani tayyor kartochka bilan menejerga uzatish","Murakkab yoki noaniq savolni xodimga o‘tkazish","Javoblarni admin paneldan tahrirlash","Suhbatlar tarixi va eng ko‘p beriladigan savollar"],"platforms":["Telegram bot","Sayt chat oynasi"],"cover":"demo","url":"","published":true,"service":"ai-yordamchi","problem":"Mijoz kechki soat 11 da narx so‘rab yozadi. Ertalab menejer javob berguncha u allaqachon boshqa joydan buyurtma qilgan bo‘ladi. Kunduzi esa menejer vaqtining katta qismi «narxi qancha?», «manzil qayerda?» degan bir xil savollarga ketadi.","steps":[{"title":"Bilim yig‘amiz","text":"Narxlar, xizmatlar, savol-javoblar va qoidalaringizni bitta bazaga jamlaymiz."},{"title":"Ohangni sozlaymiz","text":"Yordamchi qanday murojaat qilishi, nimani va’da qilmasligi va qachon xodimni chaqirishini belgilaymiz."},{"title":"Mijoz yozadi","text":"Telegram yoki saytda savol beradi, yordamchi bir zumda javob qaytaradi."},{"title":"Saralaydi","text":"Kerakli xizmat, byudjet va muddatni so‘rab, arizani to‘ldiradi."},{"title":"Uzatadi","text":"Tayyor ariza yoki javobsiz qolgan savol menejerga Telegram orqali keladi."},{"title":"Sozlab boramiz","text":"Birinchi oy suhbatlarni ko‘rib, javoblarni aniqlashtirib boramiz."}],"customerView":["Savoliga darhol, aniq javob","Narx va xizmatlar haqida tushunarli tushuntirish","Kerak bo‘lsa — tirik xodim bilan bog‘lanish","Ariza qabul qilingani haqida tasdiq"],"ownerView":["Har yangi ariza — ism, ehtiyoj, byudjet va muddat bilan","Yordamchi javob bera olmagan savollar alohida","Barcha suhbatlar tarixi","Eng ko‘p so‘raladigan savollar ro‘yxati"],"beforeAfter":[{"before":"Kechasi yozgan mijoz ertalabgacha javob kutadi","after":"Javob bir necha soniyada, kechasi ham"},{"before":"Menejer bir xil savollarga qayta-qayta javob beradi","after":"Menejerga faqat tayyor ariza va murakkab savollar keladi"},{"before":"Arizalar chatlar orasida yo‘qoladi","after":"Har ariza bitta tartibli kartochkada"},{"before":"Byudjet va muddat keyin aniqlanadi","after":"Ular arizaning o‘zida yozilgan bo‘ladi"}],"fit":["O‘quv markazlari","Klinikalar","Ko‘chmas mulk agentliklari","Ta’mirlash va qurilish","Onlayn do‘konlar","Turfirmalar"],"faq":[{"q":"Yordamchi noto‘g‘ri javob berib qo‘ymaydimi?","a":"U faqat siz bergan ma’lumotlar asosida javob beradi. Javobini bilmagan savolga o‘ylab topmaydi — mijozga xodim bog‘lanishini aytadi va savolni sizga uzatadi."},{"q":"AI xizmati uchun alohida to‘lov bormi?","a":"Ha, AI xizmati (token) sarfi alohida to‘lanadi. Suhbatlar soniga qarab oylik sarfni oldindan hisoblab beramiz."},{"q":"Narxlarim o‘zgarsa nima bo‘ladi?","a":"Admin paneldan o‘zingiz yangilaysiz — yordamchi darhol yangi ma’lumot bilan javob beradi."}],"demo":{"bot":"Bilim markazi","start":"start","nodes":[{"id":"start","messages":["Assalomu alaykum! Men Bilim o‘quv markazining yordamchisiman. Qaysi yo‘nalish qiziqtiradi?"],"buttons":[{"label":"Ingliz tili","next":"eng"},{"label":"IT kurslar","next":"it"},{"label":"Boshqa savol","next":"other"}]},{"id":"eng","messages":["Ingliz tili guruhlari: boshlang‘ichdan IELTS gacha. Darslar haftasiga 3 marta, 90 daqiqadan.","Oylik to‘lov — 450 000 so‘m. Birinchi dars bepul."],"buttons":[{"label":"Bepul darsga yozilish","next":"time"},{"label":"Qayerda joylashgansiz?","next":"address"}]},{"id":"address","messages":["Chilonzor, 9-mavze, metro yonida. Ish vaqti: 9:00–20:00, yakshanba — dam olish."],"buttons":[{"label":"Bepul darsga yozilish","next":"time"}]},{"id":"it","messages":["IT yo‘nalishida: Python, veb-dasturlash va kompyuter savodxonligi. Davomiyligi 4–6 oy.","Narx yo‘nalishga qarab oyiga 550 000–700 000 so‘m."],"buttons":[{"label":"Bepul darsga yozilish","next":"time"}]},{"id":"other","messages":["Savolingizni yozing — bilsam darhol javob beraman, bilmasam menejerimizga uzataman."],"buttons":[{"label":"«Bo‘lib to‘lash mumkinmi?»","next":"handoff"}]},{"id":"handoff","messages":["Bu savolga menejerimiz aniq javob beradi. Savolingizni unga uzatdim — 15 daqiqa ichida yozadi."],"buttons":[{"label":"Bepul darsga yozilish","next":"time"}],"owner":{"title":"Javobsiz savol → menejerga","lines":["«Bo‘lib to‘lash mumkinmi?»","Mijoz: Telegram, 23:14","Bazada javob yo‘q — xodim kerak"]}},{"id":"time","messages":["Qaysi vaqt qulay?"],"buttons":[{"label":"Ertalab, 9:00–12:00","next":"phone-am"},{"label":"Kechqurun, 17:00–20:00","next":"phone-pm"}]},{"id":"phone-am","messages":["Telefon raqamingizni yuboring — menejer vaqtni tasdiqlash uchun qo‘ng‘iroq qiladi."],"buttons":[{"label":"Raqamni yuborish","next":"done-am"}]},{"id":"phone-pm","messages":["Telefon raqamingizni yuboring — menejer vaqtni tasdiqlash uchun qo‘ng‘iroq qiladi."],"buttons":[{"label":"Raqamni yuborish","next":"done-pm"}]},{"id":"done-am","messages":["Rahmat, Dilshod! Bepul darsga yozildingiz. Menejer bugun qo‘ng‘iroq qilib, aniq kunni tasdiqlaydi."],"card":{"title":"Ariza №248","lines":["Bepul sinov darsi","Qulay vaqt: ertalab","Telefon: +998 90 *** ** 12"]},"buttons":[],"owner":{"title":"Yangi ariza №248","lines":["Dilshod · +998 90 *** ** 12","Bepul sinov darsi · ertalab","Manba: Telegram, 23:16"]}},{"id":"done-pm","messages":["Rahmat, Dilshod! Bepul darsga yozildingiz. Menejer bugun qo‘ng‘iroq qilib, aniq kunni tasdiqlaydi."],"card":{"title":"Ariza №248","lines":["Bepul sinov darsi","Qulay vaqt: kechqurun","Telefon: +998 90 *** ** 12"]},"buttons":[],"owner":{"title":"Yangi ariza №248","lines":["Dilshod · +998 90 *** ** 12","Bepul sinov darsi · kechqurun","Manba: Telegram, 23:16"]}}]}}',1);
INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('peshtaxta','peshtaxta','{"id":"peshtaxta","slug":"peshtaxta","name":"Peshtaxta","category":"Telegram","status":"Namuna","summary":"Telegram ichida ochiladigan do‘kon: katalog, savat, Payme yoki Click to‘lovi va buyurtma holati.","description":"Peshtaxtada mijoz Telegram’dan chiqmasdan mahsulot tanlaydi, to‘laydi va buyurtmasini kuzatadi (Mini App). Do‘kon savatda qolib ketgan mahsulotni eslatadi va savatga mos qo‘shimcha taklif qiladi. Sizga har buyurtma darhol keladi, kun oxirida esa savdo xulosasi.","purpose":"Direktda «narxi qancha?» deb so‘raganlarni yozishmasiz, o‘zi buyurtma beradigan mijozga aylantirish.","features":["Kategoriya, filtr va qidiruvli katalog","Savat, yetkazish yoki olib ketishni tanlash","Payme, Click yoki naqd to‘lov","Buyurtma holati: qabul qilindi, yig‘ilmoqda, yo‘lda","Savatda qolgan mahsulot haqida bir martalik eslatma","Savatga mos qo‘shimcha mahsulot taklifi","Tugagan mahsulot uchun «kelganda xabar bering» ro‘yxati","Mahsulot, narx va qoldiqni telefondan o‘zgartirish","Kunlik savdo xulosasi Telegram’ga"],"platforms":["Telegram Mini App","Telegram bot"],"cover":"demo","url":"","published":true,"service":"telegram-bot","problem":"Mahsulotlar Instagram’da, savollar direktda, buyurtmalar daftarda. Har mijozga narx, o‘lcham va yetkazishni alohida yozib tushuntirish kerak. Kechasi kelgan savol ertalabgacha javobsiz qoladi va mijoz sovib ketadi.","steps":[{"title":"Katalog","text":"Mahsulotlar, narxlar, rasmlar va qoldiqni yuklaymiz — Excel’dan ko‘chirish ham mumkin."},{"title":"Mijoz tanlaydi","text":"Bot tugmasini bosib do‘konni ochadi, filtr bilan qidiradi, savatga qo‘shadi."},{"title":"To‘lov","text":"Payme yoki Click orqali to‘laydi yoki naqd to‘lovni tanlaydi."},{"title":"Sizga xabar","text":"Buyurtma tarkibi, manzil va to‘lov holati bilan Telegram’ga keladi."},{"title":"Holat","text":"Holatni bir tugma bilan o‘zgartirasiz, mijozga avtomatik xabar boradi."},{"title":"Qaytarish","text":"Savatini tashlab ketgan mijozga keyinroq bitta muloyim eslatma boradi."}],"customerView":["Rasm, narx va o‘lchamlar bilan katalog","Bir necha bosishda buyurtma va to‘lov","Buyurtma holati haqida xabarlar","Oldingi buyurtmalar tarixi"],"ownerView":["Har yangi buyurtma — tarkibi, summasi va manzili bilan","To‘langan yoki to‘lanmagani","Kunlik va oylik savdo xulosasi","Tugab borayotgan mahsulotlar ro‘yxati"],"beforeAfter":[{"before":"Har mijozga narxni direktda alohida yozasiz","after":"Mijoz narxni katalogda o‘zi ko‘radi"},{"before":"Buyurtma daftarga yoziladi","after":"Buyurtma tarkibi va manzili bilan avtomatik saqlanadi"},{"before":"To‘lov chek rasmi bilan tekshiriladi","after":"Payme yoki Click to‘lovi o‘zi tasdiqlanadi"},{"before":"Savatni tashlab ketgan mijoz unutiladi","after":"Unga o‘z vaqtida eslatma boradi"}],"fit":["Kiyim va poyabzal","Kosmetika","Gul va sovg‘alar","Telefon aksessuarlari","Uy-ro‘zg‘or buyumlari","Qo‘l mehnati mahsulotlari"],"faq":[{"q":"Mini App bilan oddiy botning farqi nima?","a":"Oddiy botda mahsulot tugma va xabarlar orqali tanlanadi. Mini App esa Telegram ichida ochiladigan to‘liq sahifa: rasmli katalog, filtr va savat bilan. Mahsulot ko‘p bo‘lsa, Mini App qulayroq."},{"q":"Payme yoki Click’ga ulanish uchun nima kerak?","a":"To‘lov tizimida sotuvchi (merchant) hisobi kerak. Uni ochishda yordam beramiz, avval sinov rejimida tekshirib, keyin jonli ulaymiz."},{"q":"Mahsulotlarni o‘zim qo‘sha olamanmi?","a":"Ha, admin panel yoki botning admin buyruqlari orqali mahsulot, narx va qoldiqni telefoningizdan o‘zgartirasiz."}],"demo":{"bot":"Nafis butik","start":"start","nodes":[{"id":"start","messages":["Nafis butikka xush kelibsiz! Bugun nima qidiryapsiz?"],"buttons":[{"label":"Ko‘ylaklar","next":"dresses"},{"label":"Sumkalar","next":"bags"}]},{"id":"bags","messages":["Sumkalarning yangi kolleksiyasi ertaga keladi — 12 ta model. Kelishi bilan sizga xabar beraymi?"],"buttons":[{"label":"Ha, xabar bering","next":"notify"},{"label":"Ko‘ylaklarni ko‘raman","next":"dresses"}]},{"id":"notify","messages":["Yaxshi, yangi sumkalar kelishi bilan yozaman."],"buttons":[{"label":"Ko‘ylaklarni ko‘raman","next":"dresses"}],"owner":{"title":"Kutish ro‘yxati: sumkalar","lines":["+1 mijoz · jami 9 kishi","Mahsulot kelganda hammasiga xabar ketadi"]}},{"id":"dresses","messages":["Ko‘ylaklar: 24 ta model. Eng ko‘p olinadigani:"],"card":{"title":"Yozgi zig‘ir ko‘ylak","lines":["Rang: sut, zaytun","O‘lcham: S, M, L","Narx: 289 000 so‘m"]},"buttons":[{"label":"M o‘lchamni savatga","next":"cart"}]},{"id":"cart","messages":["Ko‘ylak savatda. Ko‘pchilik unga ipak ro‘mol ham oladi:"],"card":{"title":"Ipak ro‘mol","lines":["Narx: 89 000 so‘m"]},"buttons":[{"label":"Ro‘molni ham qo‘shish","next":"pay2"},{"label":"Faqat ko‘ylak","next":"pay1"}]},{"id":"pay1","messages":["Jami: 289 000 so‘m. Toshkent bo‘ylab yetkazish bepul.","Qanday to‘laysiz?"],"buttons":[{"label":"Payme","next":"paid1"},{"label":"Click","next":"paid1"}]},{"id":"pay2","messages":["Jami: 378 000 so‘m. Toshkent bo‘ylab yetkazish bepul.","Qanday to‘laysiz?"],"buttons":[{"label":"Payme","next":"paid2"},{"label":"Click","next":"paid2"}]},{"id":"paid1","messages":["To‘lov qabul qilindi. Buyurtma №1043 yig‘ilmoqda — kuryer yo‘lga chiqqanda xabar beraman."],"card":{"title":"Buyurtma №1043","lines":["Zig‘ir ko‘ylak, M — 289 000","Jami: 289 000 so‘m · to‘langan","Holat: yig‘ilmoqda"]},"buttons":[],"owner":{"title":"Yangi buyurtma №1043","lines":["Zig‘ir ko‘ylak, M — 1 dona","289 000 so‘m · to‘langan","Manzil: Yunusobod, 4-kvartal"]}},{"id":"paid2","messages":["To‘lov qabul qilindi. Buyurtma №1043 yig‘ilmoqda — kuryer yo‘lga chiqqanda xabar beraman."],"card":{"title":"Buyurtma №1043","lines":["Zig‘ir ko‘ylak, M — 289 000","Ipak ro‘mol — 89 000","Jami: 378 000 so‘m · to‘langan"]},"buttons":[],"owner":{"title":"Yangi buyurtma №1043","lines":["Zig‘ir ko‘ylak M + ipak ro‘mol","378 000 so‘m · to‘langan","Manzil: Yunusobod, 4-kvartal"]}}]}}',1);
INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('qabulxona','qabulxona','{"id":"qabulxona","slug":"qabulxona","name":"Qabulxona","category":"Telegram","status":"Namuna","summary":"Mijoz xizmat, mutaxassis va bo‘sh vaqtni o‘zi tanlab yoziladigan Telegram bot.","description":"Qabulxona — salon, klinika yoki o‘quv markazi uchun yozilish boti. Mijoz faqat bo‘sh vaqtlarni ko‘radi, bir necha bosishda yoziladi, vaqtini ko‘chiradi yoki bekor qiladi. Bot tashrifdan oldin eslatadi. Siz va mutaxassislar kunlik jadvalni Telegram’da yoki Google Sheets’da ko‘rasiz.","purpose":"Telefon orqali yozish, bir vaqtga ikki mijoz yozilib qolishi va kelmay qolgan mijozlarni kamaytirish.","features":["Xizmat, mutaxassis va bo‘sh vaqtni tanlash","Faqat haqiqatan bo‘sh vaqtlar ko‘rinadi","Vaqtni ko‘chirish yoki bekor qilish bir tugmada","Tashrifdan bir kun va 2 soat oldin eslatma","Har mutaxassisga o‘z kunlik jadvali","Google Sheets bilan bog‘lanish","Tashrifdan keyin baho so‘rash"],"platforms":["Telegram bot","Google Sheets"],"cover":"demo","url":"","published":true,"service":"telegram-bot","problem":"Administrator kun bo‘yi telefonda: kim qachon keladi, qaysi usta bo‘sh. Ba’zan ikki mijoz bir vaqtga yozilib qoladi, ba’zilari esa kelmay qoladi va vaqt bo‘sh ketadi.","steps":[{"title":"Jadval","text":"Xizmatlar, davomiyligi, mutaxassislar va ish vaqtini kiritamiz."},{"title":"Mijoz tanlaydi","text":"Bot faqat bo‘sh vaqtlarni ko‘rsatadi, mijoz o‘ziga qulayini bosadi."},{"title":"Tasdiq","text":"Mijozga yozilish tasdig‘i, mutaxassisga esa yangi yozuv keladi."},{"title":"Eslatma","text":"Bir kun va 2 soat oldin bot eslatadi; mijoz kela olmasa, vaqt boshqalarga ochiladi."},{"title":"Kun boshida","text":"Har mutaxassis o‘z jadvalini, rahbar esa umumiy jadvalni oladi."}],"customerView":["Bo‘sh vaqtlar ro‘yxati","Yozilish tasdig‘i va manzil","Tashrif oldidan eslatma","Vaqtni ko‘chirish va bekor qilish tugmalari"],"ownerView":["Har yangi yozuv darhol","Mutaxassislar bo‘yicha kunlik jadval","Bekor qilingan va ko‘chirilgan vaqtlar","Google Sheets’dagi to‘liq ro‘yxat"],"beforeAfter":[{"before":"Yozilish faqat telefon orqali","after":"Mijoz istalgan vaqtda o‘zi yoziladi"},{"before":"Bir vaqtga ikki mijoz yozilib qoladi","after":"Band vaqt boshqalarga ko‘rinmaydi"},{"before":"Mijoz unutib, kelmay qoladi","after":"Bot oldindan eslatadi"},{"before":"Bekor qilingan vaqt bo‘sh qoladi","after":"Bo‘shagan vaqt darhol boshqalarga ochiladi"}],"fit":["Go‘zallik salonlari","Barbershoplar","Stomatologiya va klinikalar","Repetitorlar","Avtoservislar","Psixolog va maslahatchilar"],"faq":[{"q":"Mijoz yozilish uchun nima qilishi kerak?","a":"Faqat botni ochib, tugmalarni bosadi. Ilova o‘rnatish yoki ro‘yxatdan o‘tish shart emas."},{"q":"Har bir usta o‘z jadvalini ko‘radimi?","a":"Ha, har mutaxassis faqat o‘z yozuvlarini oladi, rahbar esa hammasini ko‘radi."},{"q":"Telefon orqali yozilganlarni ham kiritsa bo‘ladimi?","a":"Ha, administrator ularni botga yoki jadvalga qo‘shadi — vaqt band bo‘ladi va botda ko‘rinmaydi."}],"demo":{"bot":"Lola saloni","start":"start","nodes":[{"id":"start","messages":["Assalomu alaykum! Lola go‘zallik saloniga xush kelibsiz. Nima qilamiz?"],"buttons":[{"label":"Manikyurga yozilish","next":"master"},{"label":"Narxlarni ko‘rish","next":"prices"}]},{"id":"prices","messages":["Narxlar:"],"card":{"title":"Xizmatlar","lines":["Manikyur — 120 000 so‘m · 60 daq","Soch turmagi — 180 000 so‘m · 90 daq","Kiprik — 150 000 so‘m · 75 daq"]},"buttons":[{"label":"Manikyurga yozilish","next":"master"}]},{"id":"master","messages":["Ustani tanlang:"],"buttons":[{"label":"Madina","next":"day"},{"label":"Farqi yo‘q, birinchi bo‘shi","next":"day"}]},{"id":"day","messages":["Ertaga, 21-noyabr, Madinada bo‘sh vaqtlar: 11:00 va 15:30. Qolgan vaqtlar band."],"buttons":[{"label":"15:30 ni olish","next":"confirm"},{"label":"Boshqa kun","next":"other-day"}]},{"id":"other-day","messages":["22-noyabr to‘liq band. 23-noyabrda faqat 18:30 bo‘sh. Ertangi 15:30 ni olib qo‘yaymi?"],"buttons":[{"label":"Ha, ertaga 15:30","next":"confirm"}]},{"id":"confirm","messages":["Yozildingiz! Ertaga 15:30 da kutamiz. Manzil: Mirobod, Afrosiyob ko‘chasi 12."],"card":{"title":"Yozilish","lines":["Manikyur · usta Madina","21-noyabr, 15:30","Narx: 120 000 so‘m"]},"buttons":[{"label":"Eslatma qanday keladi?","next":"remind"}],"owner":{"title":"Yangi yozuv","lines":["21-noyabr 15:30 · Madina","Manikyur · mijoz: Nilufar","Google Sheets’da yangilandi"]}},{"id":"remind","messages":["Tashrifdan 2 soat oldin shunday xabar keladi:","Bugun 15:30 da manikyurga yozilgansiz. Kelasizmi?"],"buttons":[{"label":"Ha, boraman","next":"yes"},{"label":"Vaqtni ko‘chirish","next":"move"}]},{"id":"yes","messages":["Kutamiz! Kechiksangiz, shu yerga yozib qo‘ying."],"buttons":[],"owner":{"title":"Tashrif tasdiqlandi","lines":["Nilufar · bugun 15:30 · Madina"]}},{"id":"move","messages":["Bugun Madinada 17:00 va 18:30 bo‘sh. Qaysi biri qulay?"],"buttons":[{"label":"17:00","next":"moved-17"},{"label":"18:30","next":"moved-18"}]},{"id":"moved-17","messages":["Vaqtingiz 17:00 ga ko‘chirildi. Kutamiz!"],"buttons":[],"owner":{"title":"Vaqt ko‘chirildi","lines":["Nilufar: 15:30 → 17:00","15:30 boshqa mijozlarga ochildi"]}},{"id":"moved-18","messages":["Vaqtingiz 18:30 ga ko‘chirildi. Kutamiz!"],"buttons":[],"owner":{"title":"Vaqt ko‘chirildi","lines":["Nilufar: 15:30 → 18:30","15:30 boshqa mijozlarga ochildi"]}}]}}',1);
INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('dasturxon','dasturxon','{"id":"dasturxon","slug":"dasturxon","name":"Dasturxon","category":"Telegram","status":"Namuna","summary":"Oshxona va restoranlar uchun buyurtma boti: menyu, manzil, to‘lov, oshxona va kuryer holati.","description":"Dasturxonda mijoz Telegram’da menyuni ko‘rib, taom tanlaydi, manzilini lokatsiya bilan yuboradi va to‘laydi. Buyurtma oshxonaga, tayyor bo‘lgach kuryerga o‘tadi. Mijoz har bosqichda xabar oladi, yetkazilgach esa baho qoldiradi.","purpose":"Telefon qo‘ng‘iroqlari va qo‘lda yozilgan buyurtmalardagi xatolarni yo‘qotish, taomni tezroq yetkazish.","features":["Rasmli menyu va kunning taomi","Savat va qo‘shimchalar","Manzilni lokatsiya bilan yuborish va yetkazish narxini hisoblash","Payme, Click yoki naqd to‘lov","Oshxona va kuryerlar uchun alohida chat","Holat: qabul qilindi, tayyorlanmoqda, yo‘lda, yetkazildi","Yetkazilgach baho va izoh so‘rash","Oldingi buyurtmani bir bosishda takrorlash"],"platforms":["Telegram bot","Telegram Mini App"],"cover":"demo","url":"","published":true,"service":"telegram-bot","problem":"Tushlik vaqtida telefon to‘xtamaydi: operator buyurtmani yozadi, manzilni so‘raydi, oshxonaga qog‘ozda uzatadi. Shoshilinchda bir taom tushib qoladi yoki manzil adashadi, mijoz esa «qachon keladi?» deb qayta-qayta qo‘ng‘iroq qiladi.","steps":[{"title":"Menyu","text":"Taomlar, narxlar, rasmlar va yetkazish hududini kiritamiz."},{"title":"Buyurtma","text":"Mijoz taom tanlaydi, manzilini lokatsiya bilan yuboradi va to‘laydi."},{"title":"Oshxona","text":"Buyurtma oshxona chatiga tushadi; oshpaz «tayyor» tugmasini bosadi."},{"title":"Kuryer","text":"Kuryer buyurtmani oladi, mijozga «yo‘lda» xabari boradi."},{"title":"Yetkazildi","text":"Mijozdan baho so‘raladi, kun oxirida sizga xulosa keladi."}],"customerView":["Rasmli menyu va narxlar","Yetkazish narxi va taxminiy vaqti","Buyurtma qaysi bosqichda ekani","Oldingi buyurtmani takrorlash tugmasi"],"ownerView":["Oshxona: yangi buyurtma tarkibi","Kuryer: manzil, telefon va to‘lov holati","Kun oxirida: buyurtmalar soni, tushum, baholar","Eng ko‘p sotilgan taomlar"],"beforeAfter":[{"before":"Buyurtma telefon orqali qo‘lda yoziladi","after":"Mijoz o‘zi tanlaydi, tarkib xatosiz yetib keladi"},{"before":"Manzil og‘zaki tushuntiriladi","after":"Kuryer xaritadagi aniq nuqtani oladi"},{"before":"Mijoz «qachon keladi?» deb qo‘ng‘iroq qiladi","after":"Har bosqichda o‘zi xabar oladi"},{"before":"Fikr-mulohaza yig‘ilmaydi","after":"Har yetkazishdan keyin baho bor"}],"fit":["Milliy taomlar oshxonalari","Fast-food","Kafe va restoranlar","Uy oshxonalari","Non va shirinlik sexlari","Ofislarga tushlik yetkazuvchilar"],"faq":[{"q":"Yetkazish narxi qanday hisoblanadi?","a":"Masofa yoki hudud bo‘yicha — siz qanday belgilasangiz. Mijoz lokatsiyani yuborgach, narx avtomatik chiqadi."},{"q":"O‘z kuryerlarimiz bilan ishlaydimi?","a":"Ha, kuryerlar alohida chat yoki botda buyurtma oladi va holatni bir tugma bilan o‘zgartiradi."},{"q":"Menyuni tez-tez o‘zgartiramiz, qiyin emasmi?","a":"Taom, narx va «tugadi» belgisini admin paneldan bir daqiqada o‘zgartirasiz."}],"demo":{"bot":"Navro‘z choyxonasi","start":"start","nodes":[{"id":"start","messages":["Xush kelibsiz! Bugun kunning taomi — to‘y oshi. Nima buyurtma qilasiz?"],"buttons":[{"label":"To‘y oshi · 45 000","next":"plov"},{"label":"Menyuni ochish","next":"menu"}]},{"id":"menu","messages":["Bugungi menyu:"],"card":{"title":"Menyu","lines":["To‘y oshi — 45 000","Lag‘mon — 38 000","Manti (5 dona) — 35 000","Somsa — 12 000"]},"buttons":[{"label":"To‘y oshi","next":"plov"}]},{"id":"plov","messages":["To‘y oshi savatga qo‘shildi. Manzilingizni yuboring:"],"buttons":[{"label":"Lokatsiyani yuborish","next":"priced"},{"label":"Oldingi manzil: Sergeli","next":"priced"}]},{"id":"priced","messages":["Yetkazish: 2,4 km — 8 000 so‘m, taxminan 35 daqiqa.","Jami: 53 000 so‘m. To‘lov usuli?"],"buttons":[{"label":"Click","next":"paid"},{"label":"Naqd, kuryerga","next":"cash"}]},{"id":"paid","messages":["To‘lov qabul qilindi. Buyurtmangiz oshxonaga yuborildi."],"buttons":[{"label":"Keyin nima bo‘ladi?","next":"cooking"}],"owner":{"title":"Oshxona: buyurtma №317","lines":["To‘y oshi × 1","To‘langan · Click","Tayyor bo‘lishi kerak: 12:40"]}},{"id":"cash","messages":["Yaxshi, to‘lov kuryerga naqd. Buyurtmangiz oshxonaga yuborildi."],"buttons":[{"label":"Keyin nima bo‘ladi?","next":"cooking"}],"owner":{"title":"Oshxona: buyurtma №317","lines":["To‘y oshi × 1","Naqd — kuryer 53 000 so‘m oladi","Tayyor bo‘lishi kerak: 12:40"]}},{"id":"cooking","messages":["Taomingiz tayyor, kuryer Bahodir yo‘lga chiqdi. Taxminan 20 daqiqada yetib keladi."],"buttons":[{"label":"Buyurtma yetkazildi","next":"rate"}],"owner":{"title":"Kuryer Bahodir","lines":["№317 · 2,4 km","Holat: yo‘lda"]}},{"id":"rate","messages":["Yoqimli ishtaha! Taom va yetkazishni baholang:"],"buttons":[{"label":"5 — a’lo","next":"thanks"},{"label":"3 — o‘rtacha","next":"sorry"}]},{"id":"thanks","messages":["Rahmat! Keyingi safar oldingi buyurtmani bir tugma bilan takrorlashingiz mumkin."],"buttons":[],"owner":{"title":"Baho: 5","lines":["№317 · mijoz mamnun"]}},{"id":"sorry","messages":["Rahmat, fikringiz rahbarga yetkazildi — u siz bilan bog‘lanadi."],"buttons":[],"owner":{"title":"Diqqat: baho 3","lines":["№317 · rahbarga xabar ketdi","Mijoz bilan bog‘lanish kerak"]}}]}}',1);
INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('hamkor','hamkor','{"id":"hamkor","slug":"hamkor","name":"Hamkor","category":"Telegram","status":"Namuna","summary":"Ulgurji va doimiy xaridorlar uchun buyurtma kabineti: o‘z narxi, qoldiq, qarzdorlik va takroriy buyurtma.","description":"Hamkor — do‘kon va restoranlar kabi doimiy xaridorlaringiz uchun Telegram kabineti. Mijoz telefon raqami bilan kiradi va faqat o‘ziga tegishli narxlarni, ombordagi qoldiqni va qarzdorligini ko‘radi. Oldingi buyurtmani bir bosishda takrorlaydi. Buyurtmalar hisob tizimingiz (1C, МойСклад) bilan bog‘lanadi.","purpose":"Agentlar va telefon orqali olinadigan ulgurji buyurtmalarni tez, xatosiz va kechayu kunduz qabul qilish.","features":["Telefon raqami orqali kirish — begona odam narxlarni ko‘rmaydi","Har mijozga o‘z narx turi va chegirmasi","Ombordagi qoldiq real vaqtda","Oldingi buyurtmani bir bosishda takrorlash","Qarzdorlik va to‘lov muddati","Aksiya va yangi mahsulot haqida xabar","1C yoki МойСклад bilan bog‘lanish","Agentlar uchun buyurtmalar paneli"],"platforms":["Telegram bot","Telegram Mini App","1C / МойСклад"],"cover":"demo","url":"","published":true,"service":"telegram-bot","problem":"Ulgurji mijozlar har hafta bir xil ro‘yxatni telefonda aytadi, menejer uni qayta yozadi. Qaysi mahsulot qolgani noma’lum, narxlar mijozga qarab har xil — xato oson chiqadi. Qarzdorlik esa alohida daftarda.","steps":[{"title":"Ulash","text":"Mahsulotlar, narx turlari va qoldiqlarni hisob tizimingizdan olamiz."},{"title":"Mijozlar","text":"Har mijoz telefon raqami bo‘yicha o‘z narx turi va qarz limiti bilan biriktiriladi."},{"title":"Buyurtma","text":"Mijoz katalogdan tanlaydi yoki o‘tgan buyurtmani takrorlaydi."},{"title":"Tekshiruv","text":"Bot qoldiqni va qarz limitini tekshiradi."},{"title":"Hisob tizimiga","text":"Buyurtma 1C yoki МойСкладга tushadi va omborga yig‘ish uchun boradi."},{"title":"Xabar","text":"Mijoz yig‘ilish va jo‘natish haqida xabar oladi."}],"customerView":["Faqat o‘z narxlari","Mahsulot qoldig‘i","Qarzdorlik va to‘lov muddati","Buyurtmalar tarixi va takrorlash"],"ownerView":["Har buyurtma hisob tizimida","Mijozlar bo‘yicha savdo va qarz","Uzoq vaqt buyurtma bermagan mijozlar","Agentlar kesimida buyurtmalar"],"beforeAfter":[{"before":"Buyurtma telefonda aytiladi, qayta yoziladi","after":"Mijoz o‘zi kiritadi, hisob tizimiga avtomatik tushadi"},{"before":"Qoldiq so‘rab omborga qo‘ng‘iroq qilinadi","after":"Qoldiq katalogning o‘zida"},{"before":"Har mijoz narxi eslab qolinadi","after":"Narx turi telefon raqamiga biriktirilgan"},{"before":"Qarz alohida daftarda","after":"Qarz va muddat mijozga ham, sizga ham ko‘rinadi"}],"fit":["Oziq-ovqat distribyutorlari","Qurilish mollari ulgurji savdosi","Ichimlik va suv yetkazuvchilar","Xo‘jalik mollari","Kanselyariya mollari","Ishlab chiqaruvchi korxonalar"],"faq":[{"q":"Begona odam narxlarimni ko‘rib qolmaydimi?","a":"Yo‘q. Kabinet faqat siz biriktirgan telefon raqamlariga ochiladi, har biri faqat o‘z narxlarini ko‘radi."},{"q":"Hisob tizimimiz 1C, qanday ulanadi?","a":"1C yoki МойСклад bilan mahsulot, qoldiq va buyurtmalarni almashadigan integratsiya qilamiz. Avval sinov bazasida tekshiramiz."},{"q":"Agentlarimiz ham ishlata oladimi?","a":"Ha, agent o‘z mijozlari nomidan buyurtma beradi, siz esa agentlar kesimida hisobotni ko‘rasiz."}],"demo":{"bot":"Baraka savdo","start":"start","nodes":[{"id":"start","messages":["Assalomu alaykum! Baraka savdo — hamkorlar kabineti. Kirish uchun telefon raqamingizni yuboring."],"buttons":[{"label":"Raqamni yuborish","next":"hello"}]},{"id":"hello","messages":["Xush kelibsiz, «Oila» do‘koni! Narx turingiz: ulgurji-2."],"card":{"title":"Hisobingiz","lines":["Qarzdorlik: 1 200 000 so‘m","To‘lov muddati: 25-noyabr","Qarz limiti: 10 000 000 so‘m"]},"buttons":[{"label":"O‘tgan buyurtmani takrorlash","next":"repeat"},{"label":"Katalog va aksiyalar","next":"catalog"}]},{"id":"catalog","messages":["Bo‘limlar: un va yorma, yog‘, shakar, ichimliklar. Bugungi aksiya:"],"card":{"title":"Kungaboqar yog‘i, 5 l","lines":["Sizga: 92 000 so‘m (aksiya −5%)","Omborda: 340 dona"]},"buttons":[{"label":"O‘tgan buyurtmani takrorlash","next":"repeat"}]},{"id":"repeat","messages":["12-noyabrdagi buyurtmangiz:"],"card":{"title":"Takroriy buyurtma","lines":["Un, 50 kg — 10 qop × 285 000","Shakar, 50 kg — 4 qop × 410 000","Yog‘, 5 l — 20 dona × 92 000","Jami: 6 330 000 so‘m"]},"buttons":[{"label":"Tasdiqlash","next":"stock"}]},{"id":"stock","messages":["Shakar omborda 3 qop qoldi. 3 qop bilan rasmiylashtiraymi yoki qolgan 1 qopni ertaga alohida yuboraymi?"],"buttons":[{"label":"3 qop bilan","next":"done"},{"label":"Qolganini ertaga","next":"done-split"}]},{"id":"done","messages":["Buyurtma №A-2291 qabul qilindi. Jami: 5 920 000 so‘m. Yetkazish — ertaga 10:00 gacha."],"buttons":[],"owner":{"title":"1C: yangi buyurtma №A-2291","lines":["«Oila» do‘koni · agent Sardor","5 920 000 so‘m · shakar 3 qop","Qarz limiti yetarli"]}},{"id":"done-split","messages":["Buyurtma №A-2291 qabul qilindi: bugun 5 920 000 so‘mlik, 1 qop shakar ertaga alohida keladi."],"buttons":[],"owner":{"title":"1C: buyurtma №A-2291","lines":["«Oila» do‘koni · 2 jo‘natma","Shakar 1 qop — omborga kelishi bilan","Agent: Sardor"]}}]}}',1);
INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('ovozdan-buyurtma','ovozdan-buyurtma','{"id":"ovozdan-buyurtma","slug":"ovozdan-buyurtma","name":"Ovozdan buyurtma","category":"AI","status":"Namuna","summary":"Mijoz ovozli xabar yuboradi — AI uni tartibli buyurtma kartasiga aylantiradi va jadvalga yozadi.","description":"Ko‘p mijozlar yozishdan ko‘ra gapirishni afzal ko‘radi. Ovozdan buyurtma ovozli xabarni matnga aylantiradi, undan mahsulot, miqdor, manzil va vaqtni ajratib, tartibli kartaga yig‘adi. Mijoz bir tugma bilan tasdiqlaydi, buyurtma esa jadval yoki CRM’ga tushadi. O‘zbek, rus va aralash nutqni tushunadi.","purpose":"Ovozli xabarlarni tinglab, qo‘lda qayta yozishga ketadigan vaqtni olib tashlash.","features":["Ovozli xabarni matnga aylantirish — o‘zbek, rus va aralash nutq","Mahsulot, miqdor, manzil va vaqtni ajratib olish","Tushunarsiz joyni mijozdan qayta so‘rash","Mijozga tasdiqlash va tuzatish tugmalari","Google Sheets, amoCRM yoki Bitrix24’ga yozish","Menejerga matn va asl ovoz birga"],"platforms":["Telegram bot","AI"],"cover":"demo","url":"","published":true,"service":"ai-yordamchi","problem":"Mijoz bir daqiqalik ovozli xabar yuboradi: «Assalomu alaykum, anavi kecha olgan narsadan…». Menejer uni tinglaydi, qayta tinglaydi, keyin qo‘lda yozadi. Kun oxiriga borib o‘nlab ovozli xabar yig‘iladi — ba’zilari tinglanmay qoladi.","steps":[{"title":"Ovozli xabar","text":"Mijoz botga odatdagidek gapirib yuboradi."},{"title":"Matn","text":"AI ovozni matnga aylantiradi."},{"title":"Ajratish","text":"Matndan mahsulot, miqdor, manzil va vaqt ajratib olinadi."},{"title":"Tasdiq","text":"Mijozga tayyor karta boradi, u «To‘g‘ri» yoki «Tuzatish» tugmasini bosadi."},{"title":"Yozish","text":"Tasdiqlangan buyurtma jadval yoki CRM’ga tushadi, menejerga xabar boradi."}],"customerView":["Odatdagidek ovozli xabar yuborish","Tushunilgan buyurtmaning aniq kartasi","Tasdiqlash yoki tuzatish tugmasi"],"ownerView":["Tayyor buyurtma kartasi — tinglash shart emas","Kerak bo‘lsa, asl ovozli xabar","Jadval yoki CRM’dagi yangi qator"],"beforeAfter":[{"before":"Har ovozli xabar tinglanib, qo‘lda yoziladi","after":"Buyurtma tayyor karta bo‘lib keladi"},{"before":"Miqdor yoki manzil noto‘g‘ri eshitiladi","after":"Mijoz kartani ko‘rib, o‘zi tasdiqlaydi"},{"before":"Ovozli xabarlar tinglanmay qoladi","after":"Har biri jadvalda alohida qator"}],"fit":["Suv va gaz yetkazuvchilar","Qurilish mollari do‘konlari","Ulgurji savdo","Ta’mirlash xizmatlari","Dorixonalar","Kichik ishlab chiqarish"],"faq":[{"q":"Sheva yoki aralash gapni tushunadimi?","a":"O‘zbek, rus va aralash nutqni yaxshi tushunadi. Tushunarsiz joy bo‘lsa, taxmin qilmaydi — mijozdan aniqlab so‘raydi."},{"q":"Mijoz kartani tasdiqlamasa nima bo‘ladi?","a":"«Tuzatish» tugmasi bor: mijoz o‘zgarishni yozadi yoki aytadi, karta yangilanadi."},{"q":"AI uchun qancha to‘lanadi?","a":"Ovozni matnga aylantirish va tahlil sarfi daqiqaga qarab alohida hisoblanadi; oylik taxminiy sarfni oldindan aytib beramiz."}],"demo":{"bot":"Musaffo suv","start":"start","nodes":[{"id":"start","messages":["Musaffo suv. Buyurtmangizni yozing yoki ovozli xabar yuboring."],"buttons":[{"label":"Ovozli xabar yuborish · 0:18","next":"heard"}]},{"id":"heard","messages":["Ovozli xabaringiz:\n«Assalomu alaykum, ertaga ertalab ikkita katta suv olib kelinglar, bo‘shlarini qaytaraman. Manzil o‘sha — Qoratosh 15, uchinchi qavat.»","Buyurtmangizni shunday tushundim:"],"card":{"title":"Buyurtma","lines":["Suv 19 l — 2 dona","Bo‘sh idish qaytariladi — 2 dona","Manzil: Qoratosh 15, 3-qavat","Vaqt: ertaga, 9:00–12:00","Jami: 36 000 so‘m"]},"buttons":[{"label":"To‘g‘ri","next":"ok"},{"label":"Tuzatish","next":"fix"}]},{"id":"fix","messages":["Nimani o‘zgartiramiz?"],"buttons":[{"label":"3 dona bo‘lsin","next":"ok3"},{"label":"Kechqurun olib kelinglar","next":"okpm"}]},{"id":"ok","messages":["Qabul qilindi! Kuryer ertaga 9:00–12:00 orasida keladi."],"buttons":[],"owner":{"title":"Yangi buyurtma (ovozdan)","lines":["Qoratosh 15, 3-qavat · ertaga 9–12","Suv 19 l × 2 · idish qaytadi","Google Sheets’ga yozildi · asl ovoz biriktirilgan"]}},{"id":"ok3","messages":["Yangilandi: 3 dona, jami 54 000 so‘m. Kuryer ertaga 9:00–12:00 orasida keladi."],"buttons":[],"owner":{"title":"Yangi buyurtma (ovozdan)","lines":["Qoratosh 15, 3-qavat · ertaga 9–12","Suv 19 l × 3 · 2 idish qaytadi","Mijoz miqdorni o‘zi tuzatdi"]}},{"id":"okpm","messages":["Yangilandi: ertaga 17:00–20:00. Kuryer shu oraliqda keladi."],"buttons":[],"owner":{"title":"Yangi buyurtma (ovozdan)","lines":["Qoratosh 15, 3-qavat · ertaga 17–20","Suv 19 l × 2 · idish qaytadi","Mijoz vaqtni o‘zi tuzatdi"]}}]}}',1);
INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('bir-daftar','bir-daftar','{"id":"bir-daftar","slug":"bir-daftar","name":"Bir daftar","category":"Dasturlar","status":"Namuna","summary":"Mijozlar, buyurtmalar va vazifalar bitta joyda: kichik biznes uchun CRM va uning Telegram yordamchisi.","description":"Bir daftar Excel, daftar va chatlarda tarqalgan ishni bitta tizimga jamlaydi. Har mijozning tarixi, buyurtmalari va qarzi bir sahifada. Xodimlar o‘z vazifalarini, rahbar esa kunlik va oylik hisobotni ko‘radi. Telegram yordamchisi orqali buyurtma qo‘shish, holatni o‘zgartirish va eslatma olish telefondan bir necha bosishda bo‘ladi.","purpose":"Ma’lumot yo‘qolmasligi, mijozga vaqtida qaytilishi va biznes holatini raqamlarda ko‘rish.","features":["Mijozlar bazasi: aloqa, tarix, buyurtmalar, qarz","Buyurtmalar bosqichlar bo‘yicha: yangi, jarayonda, tayyor, topshirildi","Xodimlarga vazifa va muddat","Rollar: rahbar, menejer, xodim — har biri o‘z ruxsatlari bilan","Telegram yordamchisi: buyurtma qo‘shish, holat, eslatma","Mijozga holat haqida avtomatik xabar","Kunlik va oylik hisobot, grafiklar","Excel’dagi eski ma’lumotlarni ko‘chirish va muntazam zaxira nusxa"],"platforms":["Veb-ilova","Telegram bot"],"cover":"demo","url":"","published":true,"service":"ilova","problem":"Mijozlar ro‘yxati bir xodimning telefonida, buyurtmalar Excel’da, qarzlar daftarda. Xodim ishdan ketsa, ma’lumot ham ketadi. Rahbar oy qanday o‘tganini bilish uchun kechqurun jadvallarni yig‘ib o‘tiradi.","steps":[{"title":"O‘rganish","text":"Ish jarayoningizni ko‘rib, qaysi bosqich va maydonlar kerakligini belgilaymiz."},{"title":"Ko‘chirish","text":"Excel va daftardagi mijoz va buyurtmalarni tizimga o‘tkazamiz."},{"title":"Rollar","text":"Har xodimga o‘z ruxsati: kim nimani ko‘radi va o‘zgartiradi."},{"title":"Kundalik ish","text":"Buyurtma va vazifalar tizimda yoki Telegram yordamchisi orqali yuritiladi."},{"title":"Hisobot","text":"Rahbar kunlik xulosa va oylik hisobotni oladi."}],"customerView":["Buyurtma holati haqida o‘z vaqtida xabar","Unutilmagan qo‘ng‘iroq va va’dalar","Tarixini biladigan xodim"],"ownerView":["Barcha mijoz va buyurtmalar bitta joyda","Xodimlar vazifalari va muddatlari","Kunlik xulosa Telegram’da","Oylik tushum, qarzlar va grafiklar"],"beforeAfter":[{"before":"Mijozlar xodimning telefonida","after":"Hamma ma’lumot kompaniya tizimida"},{"before":"Holatni so‘rab mijoz qo‘ng‘iroq qiladi","after":"Holat o‘zgarishi bilan mijozga xabar boradi"},{"before":"Hisobot uchun jadvallar qo‘lda yig‘iladi","after":"Hisobot har kuni tayyor"},{"before":"Qarzlar daftarda unutiladi","after":"Muddati o‘tgan qarz haqida eslatma keladi"}],"fit":["Ishlab chiqarish sexlari","Mebel va ta’mirlash","Ulgurji va chakana savdo","Xizmat ko‘rsatish kompaniyalari","O‘quv markazlari","Reklama agentliklari"],"faq":[{"q":"Tayyor CRM’dan (amoCRM, Bitrix24) farqi nima?","a":"Tayyor CRM’larda imkoniyat ko‘p, lekin ular murakkab va oylik obunali. Bir daftar faqat sizga kerakli maydon va bosqichlar bilan yasaladi, kod va ma’lumot sizniki bo‘ladi."},{"q":"Telefondan ishlasa bo‘ladimi?","a":"Ha, tizim telefonga moslashgan, eng ko‘p ishlatiladigan amallar esa Telegram yordamchisida ham bor."},{"q":"Ma’lumotlarimiz yo‘qolib qolmaydimi?","a":"Muntazam zaxira nusxa olinadi, kirish parol va rollar bilan himoyalanadi."}],"demo":{"bot":"Usta mebel · CRM","start":"start","nodes":[{"id":"start","messages":["Xayrli tong, Javlon! Bugungi ishlar:"],"card":{"title":"Bugun","lines":["3 ta buyurtma topshiriladi","2 ta qo‘ng‘iroq rejada","1 ta to‘lov muddati o‘tgan"]},"buttons":[{"label":"Yangi buyurtma qo‘shish","next":"new"},{"label":"Muddati o‘tgan to‘lov","next":"debt"}]},{"id":"new","messages":["Mijozning ismi yoki telefoni?"],"buttons":[{"label":"Dilfuza Karimova","next":"client"}]},{"id":"client","messages":["Dilfuza Karimova — 2 ta oldingi buyurtma, oxirgisi: oshxona mebeli, may oyida.","Buyurtma turi?"],"buttons":[{"label":"Shkaf-kupe","next":"created"}]},{"id":"created","messages":["Buyurtma №214 yaratildi. O‘lchov uchun usta Rustamga vazifa berildi — ertaga 11:00."],"buttons":[{"label":"Holatni o‘zgartirish","next":"status"}],"owner":{"title":"CRM: yangi buyurtma №214","lines":["Dilfuza Karimova · shkaf-kupe","Bosqich: o‘lchov · usta Rustam","Vazifa: ertaga 11:00"]}},{"id":"status","messages":["№214 qaysi bosqichga o‘tdi?"],"buttons":[{"label":"Ishlab chiqarishda","next":"status-done"}]},{"id":"status-done","messages":["Holat yangilandi. Mijozga xabar yuborildi: «Shkafingiz ishlab chiqarishda, tayyor bo‘lishiga taxminan 10 kun qoldi.»"],"buttons":[],"owner":{"title":"№214 → ishlab chiqarishda","lines":["Mijozga avtomatik xabar ketdi","Rahbar hisobotida yangilandi"]}},{"id":"debt","messages":["Muddati o‘tgan to‘lov:"],"card":{"title":"№198 · Akmal Toshev","lines":["Qoldiq: 2 400 000 so‘m","Muddat: 15-noyabr (3 kun o‘tdi)"]},"buttons":[{"label":"Mijozga eslatma yuborish","next":"debt-sent"},{"label":"Menejerga vazifa berish","next":"debt-task"}]},{"id":"debt-sent","messages":["Akmal Toshevga muloyim eslatma yuborildi. Javob kelsa, sizga yetkazaman."],"buttons":[{"label":"Yangi buyurtma qo‘shish","next":"new"}],"owner":{"title":"Qarz eslatmasi yuborildi","lines":["№198 · 2 400 000 so‘m","Mijoz javobi kutilmoqda"]}},{"id":"debt-task","messages":["Menejer Sevaraga vazifa berildi: bugun 16:00 gacha Akmal Toshevga qo‘ng‘iroq qilish."],"buttons":[{"label":"Yangi buyurtma qo‘shish","next":"new"}],"owner":{"title":"Vazifa: Sevara","lines":["Qo‘ng‘iroq: Akmal Toshev, №198","Muddat: bugun 16:00"]}}]}}',1);
INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('yagona-oqim','yagona-oqim','{"id":"yagona-oqim","slug":"yagona-oqim","name":"Yagona oqim","category":"Dasturlar","status":"Namuna","summary":"Sayt, Instagram va Telegram’dan kelgan arizalar bitta jadval yoki CRM’ga tushadi, menejerga darhol xabar boradi.","description":"Yagona oqim arizalar qayerdan kelmasin — sayt formasi, Instagram direkti, Telegram bot yoki reklama formasi — hammasini bitta ro‘yxatga yig‘adi. Har ariza manbasi bilan yoziladi, navbatdagi menejerga biriktiriladi va unga Telegram’da xabar keladi. Javobsiz qolgan ariza haqida tizim eslatadi, oy oxirida esa qaysi manba ko‘proq mijoz olib kelgani ko‘rinadi.","purpose":"Birorta ariza yo‘qolmasligi va reklama pulining qayerga ketayotganini bilish.","features":["Sayt formasi, Instagram, Telegram va reklama formalaridan yig‘ish","Google Sheets, amoCRM yoki Bitrix24’ga yozish","Navbat bo‘yicha menejerga biriktirish","Menejerga darhol Telegram xabari","Javobsiz arizani eslatish va rahbarga ko‘tarish","Bir mijozning takroriy arizalarini birlashtirish","Manbalar bo‘yicha oylik hisobot"],"platforms":["Integratsiya","Telegram bot","Google Sheets / CRM"],"cover":"demo","url":"","published":true,"service":"integratsiyalar","problem":"Arizalar besh joyga keladi: sayt formasi pochtaga, Instagram direktga, Telegram shaxsiy chatga. Menejerlar har birini alohida tekshiradi, ba’zisi bir kun kechikib ko‘riladi, ba’zisi umuman ko‘rilmaydi. Qaysi reklama ishlayotganini esa hech kim bilmaydi.","steps":[{"title":"Manbalar","text":"Sayt formasi, Instagram, Telegram va reklama formalarini ulaymiz."},{"title":"Bitta ro‘yxat","text":"Har ariza manbasi, vaqti va aloqasi bilan jadval yoki CRM’ga tushadi."},{"title":"Biriktirish","text":"Ariza navbatdagi menejerga beriladi, unga Telegram’da xabar keladi."},{"title":"Nazorat","text":"15 daqiqada javob berilmasa — menejerga eslatma, keyin rahbarga xabar."},{"title":"Hisobot","text":"Oy oxirida: qaysi manbadan nechta ariza kelgan va nechtasi mijozga aylangan."}],"customerView":["Qaysi kanalda yozsa ham tez javob","Bir xil savolni ikki marta bermaslik"],"ownerView":["Barcha arizalar bitta ro‘yxatda","Har arizaning manbasi va mas’ul menejeri","Javobsiz qolgan arizalar","Manbalar bo‘yicha oylik hisobot"],"beforeAfter":[{"before":"Arizalar besh joyda tarqalgan","after":"Hammasi bitta jadval yoki CRM’da"},{"before":"Ariza kechikib ko‘riladi","after":"Menejerga darhol xabar, kechiksa — eslatma"},{"before":"Kim javob bergani noma’lum","after":"Har ariza mas’ul menejeri bilan"},{"before":"Reklama samarasi taxmin qilinadi","after":"Har manbadan kelgan mijozlar soni aniq"}],"fit":["Ko‘chmas mulk","O‘quv markazlari","Klinikalar","Ta’mirlash va qurilish","Avtosalonlar","Reklama beradigan har qanday biznes"],"faq":[{"q":"Instagram direktini ham ulasa bo‘ladimi?","a":"Ha, Instagram biznes akkaunti orqali direkt xabarlari va reklama formalari ulanadi."},{"q":"Bizda allaqachon amoCRM bor — bu kerakmi?","a":"Ha, Yagona oqim aynan arizalarni mavjud CRM’ingizga to‘g‘ri yetkazadi. CRM bo‘lmasa, Google Sheets yetarli."},{"q":"Bitta mijoz ikki joydan yozsa-chi?","a":"Telefon yoki username bo‘yicha takroriy arizalar bitta kartaga birlashtiriladi."}],"demo":{"bot":"Yagona oqim","start":"start","nodes":[{"id":"start","messages":["Yangi ariza! Manba: Instagram reklama formasi."],"card":{"title":"Ariza №531","lines":["Ism: Shohruh","Telefon: +998 93 *** ** 47","Qiziqish: 2 xonali kvartira, Yunusobod","Mas’ul: siz (navbat bo‘yicha)"]},"buttons":[{"label":"Qo‘ng‘iroq qildim","next":"called"},{"label":"Keyinroq","next":"late"}],"owner":{"title":"Jadval: +1 ariza","lines":["№531 · Instagram · Shohruh","Holat: yangi · mas’ul: Kamola"]}},{"id":"late","messages":["Yaxshi. 15 daqiqadan keyin eslataman."],"buttons":[{"label":"15 daqiqa o‘tdi","next":"remind"}]},{"id":"remind","messages":["Eslatma: №531 hali javobsiz. Yana 15 daqiqada bog‘lanilmasa, rahbarga xabar beriladi."],"buttons":[{"label":"Qo‘ng‘iroq qildim","next":"called"}],"owner":{"title":"Javobsiz ariza: №531","lines":["15 daqiqa o‘tdi","Keyingi qadam: rahbarga xabar"]}},{"id":"called","messages":["Natija qanday?"],"buttons":[{"label":"Ko‘rishga yozildi","next":"booked"},{"label":"O‘ylab ko‘radi","next":"think"}]},{"id":"booked","messages":["Ajoyib! №531 «Ko‘rish belgilandi» bosqichiga o‘tdi."],"buttons":[{"label":"Keyingi ariza","next":"second"}],"owner":{"title":"№531 → ko‘rish belgilandi","lines":["Manba: Instagram reklama","Javob vaqti qayd etildi"]}},{"id":"think","messages":["Tushunarli. 3 kundan keyin qayta qo‘ng‘iroq qilish uchun vazifa qo‘ydim."],"buttons":[{"label":"Keyingi ariza","next":"second"}],"owner":{"title":"№531 → o‘ylab ko‘rmoqda","lines":["Vazifa: 3 kundan keyin qo‘ng‘iroq"]}},{"id":"second","messages":["Yangi ariza! Manba: sayt formasi."],"card":{"title":"Ariza №532","lines":["Ism: Shohruh","Telefon: +998 93 *** ** 47","Izoh: «Yunusoboddagi kvartira bo‘yicha»"]},"buttons":[{"label":"Kartani ochish","next":"merged"}]},{"id":"merged","messages":["Bu mijoz bugun Instagram orqali ham yozgan. Ikkala ariza №531 kartasiga birlashtirildi — ikki marta qo‘ng‘iroq qilish shart emas."],"buttons":[{"label":"Oylik hisobot","next":"report"}],"owner":{"title":"Takroriy ariza birlashtirildi","lines":["№532 → №531","Manbalar: Instagram, sayt"]}},{"id":"report","messages":["Noyabr oyi, manbalar bo‘yicha:"],"card":{"title":"Ariza → mijoz","lines":["Instagram reklama — 64 → 11","Sayt formasi — 38 → 9","Telegram — 21 → 6"]},"buttons":[]}]}}',1);
INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('kurs-sayti','kurs-sayti','{"id":"kurs-sayti","slug":"kurs-sayti","name":"Kurs sotuvchi sayt","category":"Saytlar","status":"Namuna","summary":"Kurs sahifasi, Payme yoki Click to‘lovi va to‘lovdan keyin yopiq kanalga avtomatik kirish.","description":"Kurs sotuvchi sayt — onlayn kurs yoki marafon uchun tayyor sotuv tizimi. Sahifada kurs dasturi, muallif va tariflar turadi. O‘quvchi to‘laganda tizim to‘lovni o‘zi tasdiqlaydi va Telegram bot orqali yopiq kanal yoki guruhga bir martalik havola beradi. Obuna muddati tugashidan oldin eslatadi, to‘lamaganlarni kanaldan chiqaradi.","purpose":"To‘lov cheklarini qo‘lda tekshirish va o‘quvchilarni kanalga bittalab qo‘shishdan qutulish.","features":["Kurs sahifasi: dastur, muallif, tariflar, savol-javob","Payme va Click orqali to‘lov","To‘lovdan keyin yopiq kanal yoki guruhga bir martalik havola","Havola bir kishiga, bir marta ishlaydi","Oylik obunada muddat eslatmasi va avtomatik chiqarish","Promokod va erta yozilish narxi","O‘quvchilar ro‘yxati va to‘lovlar hisobi"],"platforms":["Veb-sayt","Telegram bot"],"cover":"demo","url":"","published":true,"service":"veb-sayt","problem":"Kurs e’lon qilinganda direkt to‘lib ketadi: karta raqami yuboriladi, chek rasmi kutiladi, keyin har o‘quvchi kanalga qo‘lda qo‘shiladi. Kimdir havolani do‘stiga uzatadi, kimdir obunani to‘lamay kanalda qolib ketadi.","steps":[{"title":"Sahifa","text":"Kurs dasturi, tariflar va muallif haqida sayt sahifasini yasaymiz."},{"title":"To‘lov","text":"O‘quvchi tarifni tanlab, Payme yoki Click orqali to‘laydi."},{"title":"Tasdiq","text":"To‘lov tizimi to‘lovni avtomatik tasdiqlaydi."},{"title":"Kirish","text":"Bot o‘quvchiga bir martalik havola beradi va uni kanalga qo‘shadi."},{"title":"Muddat","text":"Oylik obunada muddat tugashidan oldin eslatma, to‘lanmasa — kanaldan chiqarish."}],"customerView":["Kurs haqida to‘liq sahifa","Kartadan bir necha bosishda to‘lov","To‘lovdan keyin darhol kanalga kirish","Obuna muddati haqida eslatma"],"ownerView":["Har to‘lov va yangi o‘quvchi haqida xabar","O‘quvchilar va tariflar ro‘yxati","Muddati tugayotgan obunalar","Promokodlar natijasi"],"beforeAfter":[{"before":"Karta raqami va chek rasmi orqali to‘lov","after":"Payme yoki Click — to‘lov o‘zi tasdiqlanadi"},{"before":"Har o‘quvchi kanalga qo‘lda qo‘shiladi","after":"Bot to‘lovdan keyin darhol qo‘shadi"},{"before":"Havola do‘stlarga tarqaladi","after":"Har havola bir kishiga, bir marta"},{"before":"To‘lamaganlar kanalda qoladi","after":"Muddat tugasa, bot avtomatik chiqaradi"}],"fit":["Onlayn kurs mualliflari","Ekspert va bloggerlar","Marafonlar","Yopiq klub va jamoalar","O‘quv markazlarining onlayn guruhlari"],"faq":[{"q":"Kurs saytning o‘zida o‘tadimi?","a":"Darslar odatdagidek yopiq Telegram kanal yoki guruhda o‘tadi. Sayt sotish va to‘lov uchun, bot esa kirish va obuna uchun javob beradi."},{"q":"Bo‘lib to‘lash mumkinmi?","a":"Ha, oylik obuna yoki bir necha qismga bo‘lingan to‘lov qilish mumkin — bot har qism muddatini kuzatadi."},{"q":"Mavjud kanalimga ulash mumkinmi?","a":"Ha, botni mavjud kanalingizga admin qilib qo‘shamiz, o‘quvchilar ro‘yxati saqlanadi."}],"demo":{"bot":"Mohir akademiya","start":"start","nodes":[{"id":"start","messages":["Assalomu alaykum! Bu «Mobil fotografiya» kursining boti. Tarifni tanlang:"],"card":{"title":"Tariflar","lines":["Standart — 390 000 so‘m · 6 hafta","Mentor bilan — 690 000 so‘m · 6 hafta + ishlar tahlili"]},"buttons":[{"label":"Standart","next":"pay"},{"label":"Promokodim bor","next":"promo"}]},{"id":"promo","messages":["«KUZ10» promokodi qabul qilindi: −10%. Standart tarif — 351 000 so‘m."],"buttons":[{"label":"To‘lovga o‘tish","next":"pay-promo"}]},{"id":"pay","messages":["To‘lov: 390 000 so‘m."],"buttons":[{"label":"Click orqali","next":"paid"},{"label":"Payme orqali","next":"paid"}]},{"id":"pay-promo","messages":["To‘lov: 351 000 so‘m."],"buttons":[{"label":"Click orqali","next":"paid-promo"},{"label":"Payme orqali","next":"paid-promo"}]},{"id":"paid","messages":["To‘lov tasdiqlandi. Xush kelibsiz, Mohira!","Yopiq kanalga kirish havolangiz — u faqat siz uchun va bir marta ishlaydi."],"card":{"title":"Kanalga kirish","lines":["«Mobil fotografiya» · 5-oqim","Darslar: dushanba va payshanba, 20:00"]},"buttons":[{"label":"Kurs tugashiga 3 kun qolganda","next":"remind"}],"owner":{"title":"Yangi o‘quvchi","lines":["Mohira S. · Standart · 390 000 so‘m","Click · kanalga qo‘shildi","5-oqimda jami 47 o‘quvchi"]}},{"id":"paid-promo","messages":["To‘lov tasdiqlandi. Xush kelibsiz, Mohira!","Yopiq kanalga kirish havolangiz — u faqat siz uchun va bir marta ishlaydi."],"card":{"title":"Kanalga kirish","lines":["«Mobil fotografiya» · 5-oqim","Darslar: dushanba va payshanba, 20:00"]},"buttons":[{"label":"Kurs tugashiga 3 kun qolganda","next":"remind"}],"owner":{"title":"Yangi o‘quvchi","lines":["Mohira S. · Standart · 351 000 so‘m","Promokod: KUZ10 · kanalga qo‘shildi","5-oqimda jami 47 o‘quvchi"]}},{"id":"remind","messages":["Kursingiz 3 kundan keyin tugaydi. Davomi — «Mobil fotografiya 2» — 15-dekabrdan. Oldindan yozilganlarga −15%."],"buttons":[{"label":"Yozilaman","next":"next"},{"label":"Hozircha yo‘q","next":"bye"}]},{"id":"next","messages":["Ajoyib! 2-oqimda siz uchun joy band qilindi, to‘lov havolasi 1-dekabrda keladi."],"buttons":[],"owner":{"title":"Oldindan yozildi: 2-oqim","lines":["Mohira S. · −15%","2-oqimga jami 12 kishi"]}},{"id":"bye","messages":["Tushunarli. Kursni tugatganingiz bilan tabriklaymiz! Kanal 3 kundan keyin yopiladi — materiallarni saqlab oling."],"buttons":[],"owner":{"title":"Obuna yakunlanmoqda","lines":["Mohira S. · 3 kundan keyin kanaldan chiqariladi"]}}]}}',1);
INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('imtihon-murabbiyi','imtihon-murabbiyi','{"id":"imtihon-murabbiyi","slug":"imtihon-murabbiyi","name":"Imtihon murabbiyi","category":"AI","status":"Namuna","summary":"Til markazlari uchun: o‘quvchining yozma va og‘zaki javobini mezonlar bo‘yicha baholaydigan AI.","description":"Imtihon murabbiyi o‘quvchi yuborgan insho yoki ovozli javobni xalqaro imtihon mezonlariga yaqin tarzda baholaydi: har mezon bo‘yicha ball, xatolar ro‘yxati va yaxshilangan variant. O‘qituvchi esa guruhda kim qayerda qiynalayotganini ko‘radi. Baho yo‘naltiruvchi — yakuniy qaror o‘qituvchida.","purpose":"O‘quvchi uyda ko‘proq mashq qilishi, o‘qituvchi esa tekshirishga kamroq vaqt sarflashi.","features":["Insho va ovozli javobni qabul qilish","Mezonlar bo‘yicha ball: vazifaga javob, izchillik, lug‘at, grammatika","Xatolar ro‘yxati va tushuntirish","Yaxshilangan variant namunasi","Kunlik mavzu va mashq","O‘qituvchiga guruh bo‘yicha haftalik hisobot","O‘quvchi rivojlanishi grafigi"],"platforms":["Telegram bot","AI"],"cover":"demo","url":"","published":true,"service":"ai-yordamchi","problem":"Til markazida bir o‘qituvchiga o‘nlab insho tushadi. Tekshirish kunlab cho‘ziladi, o‘quvchi esa javobni kutib, mashqni tashlab qo‘yadi. Og‘zaki nutqni mustaqil mashq qilish imkoni esa deyarli yo‘q.","steps":[{"title":"Topshiriq","text":"Bot har kuni mavzu beradi yoki o‘quvchi o‘z mavzusini tanlaydi."},{"title":"Javob","text":"O‘quvchi inshoni yozadi yoki ovozli javob yuboradi."},{"title":"Baholash","text":"AI mezonlar bo‘yicha ball qo‘yadi va har birini izohlaydi."},{"title":"Xatolar","text":"Xatolar ro‘yxati, to‘g‘ri variant va yaxshilangan namuna beriladi."},{"title":"Hisobot","text":"O‘qituvchi haftalik guruh hisobotini oladi: kim qaysi mezonda orqada."}],"customerView":["Kunlik topshiriq","Bir necha daqiqada ball va izoh","Xatolar va yaxshilangan variant","O‘z rivojlanish grafigi"],"ownerView":["Guruh bo‘yicha haftalik hisobot","Guruh qaysi mezonda orqada","Mashq qilmay qo‘ygan o‘quvchilar","Har o‘quvchi ishlari tarixi"],"beforeAfter":[{"before":"Insho tekshiruvi kunlab kutiladi","after":"Dastlabki baho va izoh bir necha daqiqada"},{"before":"Og‘zaki nutq faqat darsda mashq qilinadi","after":"Uyda ham ovozli javob yuborib baho olinadi"},{"before":"O‘qituvchi har inshoni boshidan tekshiradi","after":"O‘qituvchi tayyor tahlilni ko‘rib, yakuniy bahoni qo‘yadi"},{"before":"Guruhning zaif tomoni sezilmaydi","after":"Haftalik hisobotda aniq ko‘rinadi"}],"fit":["Til markazlari","IELTS va CEFR tayyorlov kurslari","Maktablar","Xususiy o‘qituvchilar","Onlayn kurslar"],"faq":[{"q":"Baho rasmiy imtihon natijasiga tengmi?","a":"Yo‘q. Baho yo‘naltiruvchi: rasmiy mezonlarga yaqin tahlil beradi, yakuniy bahoni esa o‘qituvchi qo‘yadi."},{"q":"Faqat ingliz tili uchunmi?","a":"Asosan ingliz tili uchun, lekin mezon va til sozlanadi — rus yoki boshqa til uchun ham qilish mumkin."},{"q":"O‘quvchilar ishlari kimga ko‘rinadi?","a":"Faqat markaz va o‘quvchining o‘ziga; uchinchi shaxslarga berilmaydi."}],"demo":{"bot":"Lingva murabbiy","start":"start","nodes":[{"id":"start","messages":["Salom, Aziza! Bugungi mavzu:\n«Some people think cities should ban cars from their centres. Do you agree?»","Inshoni yozing yoki ovozli javob yuboring."],"buttons":[{"label":"Insho yuborish · 264 so‘z","next":"essay"},{"label":"Ovozli javob · 1:40","next":"speaking"}]},{"id":"essay","messages":["Inshongiz tekshirildi:"],"card":{"title":"Taxminiy baho: 6.0","lines":["Vazifaga javob — 6.0","Izchillik — 6.5","Lug‘at — 5.5","Grammatika — 6.0"]},"buttons":[{"label":"Xatolarni ko‘rish","next":"errors"},{"label":"Lug‘atni qanday boyitaman?","next":"vocab"}],"owner":{"title":"Aziza R. · insho","lines":["Taxminiy 6.0 · lug‘at zaif","Bu haftadagi 4-ish"]}},{"id":"speaking","messages":["Ovozli javobingiz tahlil qilindi:"],"card":{"title":"Taxminiy baho: 6.5","lines":["Ravonlik — 6.5","Lug‘at — 6.0","Grammatika — 6.5","Talaffuz — 7.0"]},"buttons":[{"label":"Lug‘atni qanday boyitaman?","next":"vocab"}],"owner":{"title":"Aziza R. · speaking","lines":["Taxminiy 6.5 · lug‘at zaif","Bu haftadagi 4-ish"]}},{"id":"errors","messages":["Asosiy xatolar:"],"card":{"title":"3 ta xato","lines":["«more better» → «much better»","«people is» → «people are»","«In conclusion, I think that I agree» — takror; «Overall, I agree» yetarli"]},"buttons":[{"label":"Yaxshilangan variant","next":"improved"}]},{"id":"vocab","messages":["«good», «bad» va «big» so‘zlari 9 marta takrorlangan. O‘rniga: «beneficial», «harmful», «considerable». Shu so‘zlar bilan ikkita gap tuzib ko‘ring."],"buttons":[{"label":"Yaxshilangan variant","next":"improved"}]},{"id":"improved","messages":["Kirish qismining yaxshilangan varianti:\n«Banning private cars from city centres is a controversial idea, yet I believe its benefits for public health and traffic considerably outweigh the drawbacks.»"],"buttons":[{"label":"Mashqni yakunlash","next":"done"}]},{"id":"done","messages":["Barakalla! Bu hafta 4 ta ish topshirdingiz. Ertaga yangi mavzu yuboraman."],"buttons":[],"owner":{"title":"Haftalik hisobot: B2-guruh","lines":["12 o‘quvchidan 9 tasi faol","Guruhning zaif mezoni: lug‘at","2 o‘quvchi 5 kundan beri mashq qilmagan"]}}]}}',1);
INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('kontent-reja','kontent-reja','{"id":"kontent-reja","slug":"kontent-reja","name":"Kontent reja","category":"AI","status":"Namuna","summary":"Har hafta post g‘oyalari va matnlarini AI tayyorlaydi — siz faqat tasdiqlaysiz.","description":"Kontent reja biznesingiz, mahsulotlaringiz va ohangingiz asosida haftalik post rejasini tuzadi: mavzu, matn, rasm g‘oyasi va chop etish vaqti. Har dushanba reja Telegram’ga keladi, siz har postni tasdiqlaysiz, qayta yozdirasiz yoki olib tashlaysiz. Tasdiqlanganlari Google Sheets yoki Notion’dagi kontent kalendariga tushadi.","purpose":"«Bugun nima joylaymiz?» degan savolga har kuni vaqt sarflamaslik va sahifani muntazam yuritish.","features":["Biznesingiz va ohangingizga moslangan matnlar","Haftalik reja: mavzu, matn, rasm g‘oyasi, vaqt","Har postni tasdiqlash, qayta yozdirish yoki olib tashlash","Bayram va mavsumiy sanalarni hisobga olish","Google Sheets yoki Notion kontent kalendari","Telegram kanalga avtomatik joylash","Instagram va Telegram uchun alohida format"],"platforms":["Telegram bot","AI","Notion / Google Sheets"],"cover":"demo","url":"","published":true,"service":"ai-yordamchi","problem":"Sahifa haftalab yangilanmay qoladi: ish ko‘p, post yozishga vaqt yo‘q. SMM mutaxassisi qimmat yoki biznesni yaxshi bilmaydi. Natijada postlar tasodifiy va bir-biriga o‘xshash chiqadi.","steps":[{"title":"Tanishuv","text":"Biznesingiz, mahsulotlar, mijozlar va ohangingizni bir marta yozib olamiz."},{"title":"Reja","text":"Har dushanba AI haftalik reja tuzadi."},{"title":"Tasdiq","text":"Siz har postni Telegram’da tasdiqlaysiz yoki qayta yozdirasiz."},{"title":"Kalendar","text":"Tasdiqlangan postlar kontent kalendariga tushadi."},{"title":"Chop etish","text":"Belgilangan vaqtda post kanalga chiqadi, Instagram uchun matn sizga keladi."}],"customerView":["Muntazam va tartibli postlar","Mahsulot va aksiyalar haqida o‘z vaqtida xabar","Bir xil ohang va uslub"],"ownerView":["Har dushanba tayyor haftalik reja","Har post uchun tasdiq tugmalari","Kontent kalendari Notion yoki jadvalda","Chop etish vaqtida tayyor matn"],"beforeAfter":[{"before":"Post yozishga har kuni vaqt ketadi","after":"Haftalik reja bir martada tasdiqlanadi"},{"before":"Sahifa haftalab jim turadi","after":"Postlar reja bo‘yicha muntazam chiqadi"},{"before":"G‘oya topish qiyin","after":"Har hafta mavsum va mahsulotga mos g‘oyalar tayyor"}],"fit":["Kafe va restoranlar","Go‘zallik salonlari","O‘quv markazlari","Onlayn do‘konlar","Shaxsiy brend va ekspertlar","Klinikalar"],"faq":[{"q":"Matnlar «robotdek» chiqmaydimi?","a":"Boshida ohangingizni sozlaymiz va eng yaxshi postlaringizni namuna qilib beramiz. Har postni baribir siz tasdiqlaysiz."},{"q":"Postlarni o‘zi joylaydimi?","a":"Telegram kanalga avtomatik joylashi mumkin. Instagram uchun esa tayyor matn va rasm g‘oyasi chop etish vaqtida sizga keladi."},{"q":"Rasm ham tayyorlaydimi?","a":"Har post uchun aniq rasm g‘oyasini yozadi; kerak bo‘lsa, AI bilan rasm yaratishni ham ulaymiz."}],"demo":{"bot":"Shirin lahza · reja","start":"start","nodes":[{"id":"start","messages":["Xayrli tong! Shirin lahza qandolatxonasi uchun bu haftaning rejasi tayyor: 5 ta post."],"card":{"title":"Hafta rejasi","lines":["Du — Yangi mahsulot: pista tort","Cho — Tort qanday tayyorlanadi","Ju — Savol: buyurtma necha kun oldin?","Sha — Dam olish kuni aksiyasi","Yak — Jamoa bilan tanishuv"]},"buttons":[{"label":"Dushanba postini ko‘rish","next":"mon"}]},{"id":"mon","messages":["Dushanba, 10:00 · Instagram va Telegram"],"card":{"title":"Pista tort keldi","lines":["Yengil krem, qarsildoq pista va ozgina tuz — yangi tortimiz shu haftadan vitrinada.","Butun tort buyurtmasi 1 kun oldin qabul qilinadi.","Rasm g‘oyasi: kesilgan bo‘lak, yon tomondan, kunduzgi yorug‘lik"]},"buttons":[{"label":"Tasdiqlash","next":"ok"},{"label":"Qisqaroq qil","next":"short"}]},{"id":"short","messages":["Qisqa variant:"],"card":{"title":"Pista tort keldi","lines":["Pista, krem va qarsildoq qatlam. Shu haftadan vitrinada — butun tortni 1 kun oldin buyurtma qiling."]},"buttons":[{"label":"Tasdiqlash","next":"ok"}]},{"id":"ok","messages":["Tasdiqlandi. Post dushanba 10:00 da kanalga chiqadi, Instagram uchun matn shu vaqtda sizga keladi."],"buttons":[{"label":"Qolganlarini ham tasdiqlash","next":"all"}],"owner":{"title":"Kontent kalendari","lines":["Du 10:00 — Pista tort · tasdiqlandi","Qolgan 4 post tasdiq kutmoqda","Notion’da yangilandi"]}},{"id":"all","messages":["Barcha 5 ta post tasdiqlandi. Keyingi reja — kelasi dushanba."],"buttons":[],"owner":{"title":"Hafta rejasi tayyor","lines":["5/5 post tasdiqlandi","Kanal: avtomatik · Instagram: eslatma bilan"]}}]}}',1);
INSERT OR IGNORE INTO projects(id,slug,data,published) VALUES('jamoa','jamoa','{"id":"jamoa","slug":"jamoa","name":"Jamoa","category":"Dasturlar","status":"Namuna","summary":"Xodimlar uchun ichki bot: kelish-ketish, kunlik vazifalar, hisobot va rahbarga kun yakuni.","description":"Jamoa — xodimlar har kuni ishlatadigan ichki Telegram bot. Xodim ishga kelganda lokatsiya bilan belgilanadi, kunlik vazifalarini oladi, bajarganini rasm yoki izoh bilan topshiradi. Ta’til va ruxsat so‘rovlari ham shu yerda. Rahbar kun oxirida kim kelgani, kim kechikkani va qaysi vazifalar bajarilmagani haqida xulosa oladi.","purpose":"Nazoratni qo‘ng‘iroq va guruh chatlaridagi tartibsizlikdan bitta tushunarli tizimga o‘tkazish.","features":["Kelish-ketishni lokatsiya bilan belgilash","Har xodimga kunlik vazifalar va muddatlar","Vazifani rasm yoki izoh bilan topshirish","Ta’til, kasallik va ruxsat so‘rovlari","Rahbarga kun yakuni xulosasi","Oylik davomat jadvali — oylik hisoblash uchun","Filiallar va bo‘limlar bo‘yicha"],"platforms":["Telegram bot","Veb-panel"],"cover":"demo","url":"","published":true,"service":"ilova","problem":"Kim ishga keldi, kim kechikdi — rahbar buni qo‘ng‘iroq qilib bilib oladi. Vazifalar umumiy guruhda beriladi va xabarlar orasida yo‘qoladi. Oy oxirida davomat va oylik hisobi bahsga aylanadi.","steps":[{"title":"Sozlash","text":"Xodimlar, filiallar, ish vaqti va lokatsiyalarni kiritamiz."},{"title":"Kelish","text":"Xodim botda «Keldim» tugmasini bosib, lokatsiyasini yuboradi."},{"title":"Vazifalar","text":"Xodim kunlik vazifalarini oladi va bajarganini topshiradi."},{"title":"So‘rovlar","text":"Ta’til yoki ruxsat so‘rovi rahbarga boradi, u bir tugmada hal qiladi."},{"title":"Kun yakuni","text":"Rahbar davomat va vazifalar bo‘yicha xulosa oladi."}],"customerView":[],"ownerView":["Kim keldi, kim kechikdi — har kuni ertalab","Bajarilmagan vazifalar","Ta’til va ruxsat so‘rovlari bir tugmada","Oylik davomat jadvali"],"beforeAfter":[{"before":"Davomat qo‘ng‘iroq qilib aniqlanadi","after":"Har kuni ertalab tayyor ro‘yxat"},{"before":"Vazifalar guruh chatida yo‘qoladi","after":"Har xodimda o‘z vazifalari ro‘yxati"},{"before":"Bajarilgan ish so‘zda qoladi","after":"Rasm yoki izoh bilan topshiriladi"},{"before":"Oylik hisobi bahsli","after":"Davomat jadvali aniq"}],"fit":["Do‘konlar tarmog‘i","Kafe va restoranlar","Qurilish brigadalari","Tozalash xizmatlari","Ishlab chiqarish","Filiallari bor kompaniyalar"],"faq":[{"q":"Xodim uydan turib «Keldim» bosa olmaydimi?","a":"Bot lokatsiyani tekshiradi: belgilash faqat ish joyidan belgilangan masofada qabul qilinadi."},{"q":"Ko‘p filialda ishlaydimi?","a":"Ha, har filialning o‘z lokatsiyasi, ish vaqti va mas’uli bo‘ladi; rahbar umumiy va filial bo‘yicha xulosa oladi."},{"q":"Oylikni ham hisoblaydimi?","a":"Davomat va kechikishlar jadvali oylik hisoblash uchun tayyor bo‘ladi; hisob tizimingizga ham ulash mumkin."}],"demo":{"bot":"Sifat · jamoa","start":"start","nodes":[{"id":"start","messages":["Xayrli tong, Oybek! Ish 9:00 da boshlanadi."],"buttons":[{"label":"Keldim · lokatsiya","next":"in"}]},{"id":"in","messages":["Belgilandi: 8:52, Chilonzor filiali. Bugungi vazifalaringiz:"],"card":{"title":"Vazifalar · 3","lines":["1. Yangi mahsulotni vitrinaga terish","2. Kassa hisobotini 18:00 gacha topshirish","3. Ombordagi qoldiqni sanash"]},"buttons":[{"label":"1-vazifa bajarildi","next":"task1"},{"label":"Ruxsat so‘rash","next":"leave"}],"owner":{"title":"Davomat: Chilonzor","lines":["Oybek — 8:52","Sardor — hali kelmadi"]}},{"id":"task1","messages":["Vitrina rasmini yuboring — rahbar ko‘rishi uchun."],"buttons":[{"label":"Rasm yuborish","next":"task1-done"}]},{"id":"task1-done","messages":["Qabul qilindi. 2 ta vazifa qoldi."],"buttons":[{"label":"Kun yakuni","next":"summary"}],"owner":{"title":"Vazifa bajarildi","lines":["Oybek: vitrina tayyor · rasm bilan","Chilonzor · 10:14"]}},{"id":"leave","messages":["Qachon va nima sababdan?"],"buttons":[{"label":"Ertaga, oilaviy sabab","next":"leave-sent"}]},{"id":"leave-sent","messages":["So‘rovingiz rahbarga yuborildi. Javob kelishi bilan xabar beraman."],"buttons":[{"label":"Rahbar javobi","next":"leave-ok"}],"owner":{"title":"Ruxsat so‘rovi","lines":["Oybek · ertaga · oilaviy sabab","Ruxsat berish / Rad etish"]}},{"id":"leave-ok","messages":["Rahbar ruxsat berdi: ertaga dam olasiz. O‘rningizga Sardor biriktirildi."],"buttons":[{"label":"Kun yakuni","next":"summary"}],"owner":{"title":"Ruxsat berildi","lines":["Oybek — ertaga dam","O‘rniga: Sardor"]}},{"id":"summary","messages":["Bugungi ish yakunlandi. Xulosa rahbarga yuborildi."],"buttons":[],"owner":{"title":"Kun yakuni · 20-noyabr","lines":["Kelganlar: 14/15 · kechikkan: 1","Vazifalar: 38/42 bajarildi","Bajarilmagan 4 ta — ertaga ko‘chirildi"]}}]}}',1);
